function [d] = valve_duty(on, dt, s)
%VALVE_DUTY  A valve word (its on-time in counts) as the duty over a control step dt.
%   on: int (passed a whole number)
%   dt: real[s] (passed in s)
%   s: EmuScale (passed rec)
%   returns d: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = 0;
    d = ((on * s.valve) / dt);
end
